import boto3

dynamodb = boto3.resource('dynamodb')

table = dynamodb.Table('OnboardingNotes')


def store_note(user_id, note, metadata):
    response = table.put_item(
        Item={
            'user_id': user_id,
            'note': note,
            'metadata': metadata
        }
    )
    return response


def get_note(user_id):
    response = table.get_item(
        Key={'user_id': user_id}
    )
    return response.get('Item', None)

import boto3

comprehend = boto3.client('comprehend')

def moderate_profile_text(text):
    response = comprehend.detect_toxic_content(
        Text=text,
        LanguageCode='en'
    )
    if response['ToxicContentDetected']:
        return 'Profile text contains toxic content.'
    else:
        return 'Profile text is acceptable.'

if __name__ == '__main__':
    profile_text = 'Sample profile text to moderate.'
    result = moderate_profile_text(profile_text)
